macro_rules! impl_156 {
    () => {
        deps!();
        impl DateTime < FixedOffset > { # [doc = " Parses an RFC 2822 date-and-time string into a `DateTime<FixedOffset>` value."] # [doc = ""] # [doc = " This parses valid RFC 2822 datetime strings (such as `Tue, 1 Jul 2003 10:52:37 +0200`)"] # [doc = " and returns a new [`DateTime`] instance with the parsed timezone as the [`FixedOffset`]."] # [doc = ""] # [doc = " RFC 2822 is the internet message standard that specifies the representation of times in HTTP"] # [doc = " and email headers. It is the 2001 revision of RFC 822, and is itself revised as RFC 5322 in"] # [doc = " 2008."] # [doc = ""] # [doc = " # Support for the obsolete date format"] # [doc = ""] # [doc = " - A 2-digit year is interpreted to be a year in 1950-2049."] # [doc = " - The standard allows comments and whitespace between many of the tokens. See [4.3] and"] # [doc = "   [Appendix A.5]"] # [doc = " - Single letter 'military' time zone names are parsed as a `-0000` offset."] # [doc = "   They were defined with the wrong sign in RFC 822 and corrected in RFC 2822. But because"] # [doc = "   the meaning is now ambiguous, the standard says they should be considered as `-0000`"] # [doc = "   unless there is out-of-band information confirming their meaning."] # [doc = "   The exception is `Z`, which remains identical to `+0000`."] # [doc = ""] # [doc = " [4.3]: https://www.rfc-editor.org/rfc/rfc2822#section-4.3"] # [doc = " [Appendix A.5]: https://www.rfc-editor.org/rfc/rfc2822#appendix-A.5"] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " # use chrono::{DateTime, FixedOffset, TimeZone};"] # [doc = " assert_eq!("] # [doc = "     DateTime::parse_from_rfc2822(\"Wed, 18 Feb 2015 23:16:09 GMT\").unwrap(),"] # [doc = "     FixedOffset::east_opt(0).unwrap().with_ymd_and_hms(2015, 2, 18, 23, 16, 9).unwrap()"] # [doc = " );"] # [doc = " ```"] pub fn parse_from_rfc2822 (s : & str) -> ParseResult < DateTime < FixedOffset > > { const ITEMS : & [Item < 'static >] = & [Item :: Fixed (Fixed :: RFC2822)] ; let mut parsed = Parsed :: new () ; parse (& mut parsed , s , ITEMS . iter ()) ? ; parsed . to_datetime () } # [doc = " Parses an RFC 3339 date-and-time string into a `DateTime<FixedOffset>` value."] # [doc = ""] # [doc = " Parses all valid RFC 3339 values (as well as the subset of valid ISO 8601 values that are"] # [doc = " also valid RFC 3339 date-and-time values) and returns a new [`DateTime`] with a"] # [doc = " [`FixedOffset`] corresponding to the parsed timezone. While RFC 3339 values come in a wide"] # [doc = " variety of shapes and sizes, `1996-12-19T16:39:57-08:00` is an example of the most commonly"] # [doc = " encountered variety of RFC 3339 formats."] # [doc = ""] # [doc = " Why isn't this named `parse_from_iso8601`? That's because ISO 8601 allows representing"] # [doc = " values in a wide range of formats, only some of which represent actual date-and-time"] # [doc = " instances (rather than periods, ranges, dates, or times). Some valid ISO 8601 values are"] # [doc = " also simultaneously valid RFC 3339 values, but not all RFC 3339 values are valid ISO 8601"] # [doc = " values (or the other way around)."] pub fn parse_from_rfc3339 (s : & str) -> ParseResult < DateTime < FixedOffset > > { parse_rfc3339 (s) } # [doc = " Parses a string from a user-specified format into a `DateTime<FixedOffset>` value."] # [doc = ""] # [doc = " Note that this method *requires a timezone* in the input string. See"] # [doc = " [`NaiveDateTime::parse_from_str`](./naive/struct.NaiveDateTime.html#method.parse_from_str)"] # [doc = " for a version that does not require a timezone in the to-be-parsed str. The returned"] # [doc = " [`DateTime`] value will have a [`FixedOffset`] reflecting the parsed timezone."] # [doc = ""] # [doc = " See the [`format::strftime` module](crate::format::strftime) for supported format"] # [doc = " sequences."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " use chrono::{DateTime, FixedOffset, NaiveDate, TimeZone};"] # [doc = ""] # [doc = " let dt = DateTime::parse_from_str(\"1983 Apr 13 12:09:14.274 +0000\", \"%Y %b %d %H:%M:%S%.3f %z\");"] # [doc = " assert_eq!("] # [doc = "     dt,"] # [doc = "     Ok(FixedOffset::east_opt(0)"] # [doc = "         .unwrap()"] # [doc = "         .from_local_datetime("] # [doc = "             &NaiveDate::from_ymd_opt(1983, 4, 13)"] # [doc = "                 .unwrap()"] # [doc = "                 .and_hms_milli_opt(12, 9, 14, 274)"] # [doc = "                 .unwrap()"] # [doc = "         )"] # [doc = "         .unwrap())"] # [doc = " );"] # [doc = " ```"] pub fn parse_from_str (s : & str , fmt : & str) -> ParseResult < DateTime < FixedOffset > > { let mut parsed = Parsed :: new () ; parse (& mut parsed , s , StrftimeItems :: new (fmt)) ? ; parsed . to_datetime () } # [doc = " Parses a string from a user-specified format into a `DateTime<FixedOffset>` value, and a"] # [doc = " slice with the remaining portion of the string."] # [doc = ""] # [doc = " Note that this method *requires a timezone* in the input string. See"] # [doc = " [`NaiveDateTime::parse_and_remainder`] for a version that does not"] # [doc = " require a timezone in `s`. The returned [`DateTime`] value will have a [`FixedOffset`]"] # [doc = " reflecting the parsed timezone."] # [doc = ""] # [doc = " See the [`format::strftime` module](./format/strftime/index.html) for supported format"] # [doc = " sequences."] # [doc = ""] # [doc = " Similar to [`parse_from_str`](#method.parse_from_str)."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " # use chrono::{DateTime, FixedOffset, TimeZone};"] # [doc = " let (datetime, remainder) = DateTime::parse_and_remainder("] # [doc = "     \"2015-02-18 23:16:09 +0200 trailing text\","] # [doc = "     \"%Y-%m-%d %H:%M:%S %z\","] # [doc = " )"] # [doc = " .unwrap();"] # [doc = " assert_eq!("] # [doc = "     datetime,"] # [doc = "     FixedOffset::east_opt(2 * 3600).unwrap().with_ymd_and_hms(2015, 2, 18, 23, 16, 9).unwrap()"] # [doc = " );"] # [doc = " assert_eq!(remainder, \" trailing text\");"] # [doc = " ```"] pub fn parse_and_remainder < 'a > (s : & 'a str , fmt : & str ,) -> ParseResult < (DateTime < FixedOffset > , & 'a str) > { let mut parsed = Parsed :: new () ; let remainder = parse_and_remainder (& mut parsed , s , StrftimeItems :: new (fmt)) ? ; parsed . to_datetime () . map (| d | (d , remainder)) } }
    };
}

